


-- Handbook v1.14 remediation: convert simultaneous placeholder parcels into a dated, varied
-- synthetic delivery history that ends before the task begins.
PRAGMA foreign_keys=OFF;
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'interpretingshorthand notebooktranslated business textshop' WHEN 1 THEN 'translated business textitementranceshop' WHEN 2 THEN 'publictranslated business textbookstore' WHEN 3 THEN 'translated business textstorageshop'
      WHEN 4 THEN 'stationerytranslated business textstation' WHEN 5 THEN 'translated business textlinetranslated business texthome' WHEN 6 THEN 'hometranslated business textdaysuppliesshop' WHEN 7 THEN 'printingservicecenter'
      WHEN 8 THEN 'translated business textroadtranslated business text' WHEN 9 THEN 'translated business textcentertranslated business textshop' WHEN 10 THEN 'translated business textsuppliestranslated business text' WHEN 11 THEN 'translated business textadaptershop'
      WHEN 12 THEN 'thermosspecialty shop' WHEN 13 THEN 'translated business textdaysuppliesshop' WHEN 14 THEN 'translated business texthome' WHEN 15 THEN 'translated business textshop'
      ELSE 'translated business text' END AS sender_name,
    CASE rowid % 19
      WHEN 0 THEN 'translated business textpracticethis' WHEN 1 THEN 'USB translated business text' WHEN 2 THEN 'public sample questionsprintingtranslated business text' WHEN 3 THEN 'translated business textstoragetranslated business text'
      WHEN 4 THEN 'backuptranslated business textline' WHEN 5 THEN 'filetranslated business text' WHEN 6 THEN 'translated business text' WHEN 7 THEN 'translated business text'
      WHEN 8 THEN 'translated business textcup' WHEN 9 THEN 'stationerytranslated business textparcel' WHEN 10 THEN 'translated business text' WHEN 11 THEN 'translated business textstoragetranslated business text'
      WHEN 12 THEN 'equipmenttranslated business text' WHEN 13 THEN 'printingtranslated business text' WHEN 14 THEN 'charging cable' WHEN 15 THEN 'translated business text'
      WHEN 16 THEN 'publictranslated business text' WHEN 17 THEN 'translated business textlinetranslated business textstoragetranslated business text' ELSE 'translated business textitemtranslated business text' END AS parcel_item
  FROM shipments WHERE shipment_id LIKE 'SHIP_INTERP_DIST_%'
)
UPDATE shipments
SET carrier=CASE rowid % 5 WHEN 0 THEN 'translated business textroadtranslated business text' WHEN 1 THEN 'translated business textparcel' WHEN 2 THEN 'synthetictranslated business text' WHEN 3 THEN 'translated business text' ELSE 'translated business textsuppliesdelivery logistics' END,
    service_level=CASE rowid % 3 WHEN 0 THEN 'standard' WHEN 1 THEN 'economy' ELSE 'next_day' END,
    status=CASE rowid % 11 WHEN 0 THEN 'returned' WHEN 1 THEN 'cancelled' WHEN 2 THEN 'in_transit' ELSE 'delivered' END,
    sender_json=json_object('name',(SELECT sender_name FROM facts WHERE facts.rid=shipments.rowid),'item',(SELECT parcel_item FROM facts WHERE facts.rid=shipments.rowid),'synthetic',1),
    recipient_json=json_object('name','Lin Qiaoxi','phone','13800000000','city','Hangzhou','delivery_note',CASE rowid % 4 WHEN 0 THEN 'beforetranslated business text' WHEN 1 THEN 'translated business text' WHEN 2 THEN 'translated business text' ELSE 'thispersonreceipt' END),
    weight_kg=0.15 + ((rowid % 9) * 0.12),
    dimensions_json=json_object('size_class',CASE rowid % 3 WHEN 0 THEN 'small' WHEN 1 THEN 'medium' ELSE 'flat' END,'fragile',CASE rowid % 7 WHEN 0 THEN 1 ELSE 0 END),
    declared_value_minor=1800 + ((rowid * 137) % 18000),
    fee_minor=600 + ((rowid * 53) % 900),
    created_at=date('2026-04-08','+' || CAST((rowid-2)/2 AS INTEGER) || ' days') || CASE rowid % 2 WHEN 0 THEN 'T09:20:00+08:00' ELSE 'T15:40:00+08:00' END,
    eta_date=date('2026-04-10','+' || CAST((rowid-2)/2 AS INTEGER) || ' days'),
    updated_at=date('2026-04-10','+' || CAST((rowid-2)/2 AS INTEGER) || ' days') || 'T18:00:00+08:00',
    cancel_reason=CASE rowid % 11 WHEN 1 THEN 'translated business texthomeattranslated business textbeforecanceltranslated business textsupplies' ELSE NULL END,
    tracking_no=replace(tracking_no,'TRK-INTERP-','TRK-HISTORY-'),
    shipment_id=replace(shipment_id,'SHIP_INTERP_DIST_','SHIP_INTERP_HISTORY_')
WHERE shipment_id LIKE 'SHIP_INTERP_DIST_%';

UPDATE shipment_events
SET shipment_id=replace(shipment_id,'SHIP_INTERP_DIST_','SHIP_INTERP_HISTORY_'),
    event_id=replace(event_id,'DLE_INTERP_','DLE_INTERP_HISTORY_'),
    at=(SELECT updated_at FROM shipments WHERE shipments.shipment_id=replace(shipment_events.shipment_id,'SHIP_INTERP_DIST_','SHIP_INTERP_HISTORY_')),
    location=CASE rowid % 7 WHEN 0 THEN 'Hangzhoutranslated business textstationpoint' WHEN 1 THEN 'Hangzhou Eastsorting center' WHEN 2 THEN 'Nanjingtranslated business textcenter' WHEN 3 THEN 'translated business textcenter' WHEN 4 THEN 'Hangzhoutranslated business text' WHEN 5 THEN 'translated business texthomewarehouse' ELSE 'translated business textbeforetranslated business text' END,
    status_code=(SELECT status FROM shipments WHERE shipments.shipment_id=replace(shipment_events.shipment_id,'SHIP_INTERP_DIST_','SHIP_INTERP_HISTORY_')),
    description=CASE rowid % 7
      WHEN 0 THEN 'translated business textsuppliesalreadydeliveredbeforetranslated business textcompletereceiptrecord。'
      WHEN 1 THEN 'parcelattranslated business textbeforetranslated business texthomepleasetranslated business textcancel，not yettranslated business textaftertranslated business text。'
      WHEN 2 THEN 'translated business textitemtranslated business textattranslated business text，translated business text ETA update。'
      WHEN 3 THEN 'translated business textitemalreadytranslated business texthomewarehousetranslated business text，delivery logisticstranslated business textroadtranslated business text。'
      WHEN 4 THEN 'translated business textcompletetranslated business text，translated business textitemreminderalreadytranslated business text。'
      WHEN 5 THEN 'translated business textaftercompletethispersonreceipt。'
      ELSE 'parceltranslated business textsorting centertranslated business text，statusandcarrierrecordtranslated business text。' END
WHERE event_id LIKE 'DLE_INTERP_%' AND shipment_id LIKE 'SHIP_INTERP_DIST_%';
PRAGMA foreign_keys=ON;

UPDATE shipment_events
SET description=description || ' translated business textsynthetictranslated business text' ||
    json_extract((SELECT sender_json FROM shipments WHERE shipments.shipment_id=shipment_events.shipment_id),'$.item') ||
    '，senderfor' || json_extract((SELECT sender_json FROM shipments WHERE shipments.shipment_id=shipment_events.shipment_id),'$.name') || '。'
WHERE event_id LIKE 'DLE_INTERP_HISTORY_%';

-- The baseline shipment record is an old logistics snapshot. Its later
-- exception and delivery timestamps are injected by releases 000 and 006.
UPDATE shipments
SET created_at = '2026-08-01T08:00:00+08:00',
    updated_at = '2026-08-01T08:00:00+08:00'
WHERE shipment_id = 'SHIP-HEADSET-0806';

UPDATE shipment_events
SET at = '2026-08-01T08:00:00+08:00'
WHERE shipment_id = 'SHIP-HEADSET-0806';
